module arcaea_diversity(\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] n,\n    input [3:0] k,\n    // Unawakened Frag values\n    input [7:0] g_0,\n    input [7:0] g_1,\n    input [7:0] g_2,\n    input [7:0] g_3,\n    // Unawakened Step values\n    input [7:0] p_0,\n    input [7:0] p_1,\n    input [7:0] p_2,\n    input [7:0] p_3,\n    // Awakened Frag values\n    input [7:0] ga_0,\n    input [7:0] ga_1,\n    input [7:0] ga_2,\n    input [7:0] ga_3,\n    // Awakened Step values\n    input [7:0] pa_0,\n    input [7:0] pa_1,\n    input [7:0] pa_2,\n    input [7:0] pa_3,\n    output reg [3:0] result,\n    output reg done\n);\n\n    // State declarations\n    localparam [3:0] IDLE          = 4'd0;\n    localparam [3:0] CAPTURE       = 4'd1;\n    localparam [3:0] INIT_SUBSET   = 4'd2;\n    localparam [3:0] PROCESS_SUBSET= 4'd3;\n    localparam [3:0] CALC_ANTICHAIN= 4'd4;\n    localparam [3:0] UPDATE_MAX    = 4'd5;\n    localparam [3:0] NEXT_SUBSET   = 4'd6;\n    localparam [3:0] FINISH        = 4'd7;\n    reg [3:0] state, next_state;\n\n    // Internal registers\n    reg [7:0] g_reg [0:3];\n    reg [7:0] p_reg [0:3];\n    reg [7:0] ga_reg [0:3];\n    reg [7:0] pa_reg [0:3];\n    reg [3:0] n_reg;\n    reg [3:0] k_reg;\n\n    reg [3:0] awakenable_partners;\n    reg [3:0] subset_mask;\n    reg [3:0] subset_size;\n    reg [3:0] max_diversity;\n\n    reg [7:0] curr_frag [0:3];\n    reg [7:0] curr_step [0:3];\n\n    reg [15:0] subset_candidate;\n    reg [3:0] antichain_max;\n    reg [15:0] s_mask;\n    reg [3:0] s_size;\n\n    integer i, j, m;\n    reg valid_antichain;\n    reg valid_pair;\n    reg [7:0] cycle_counter;\n    localparam [7:0] MAX_CYCLES = 8'd200;\n\n    // State machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 4'd0;\n            done <= 1'b0;\n            max_diversity <= 4'd0;\n            subset_mask <= 4'd0;\n            for (i = 0; i < 4; i = i + 1) begin\n                g_reg[i] <= 8'd0;\n                p_reg[i] <= 8'd0;\n                ga_reg[i] <= 8'd0;\n                pa_reg[i] <= 8'd0;\n            end\n            cycle_counter <= 8'd0;\n        end else begin\n            cycle_counter <= cycle_counter + 8'd1;\n            state <= next_state;\n\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        next_state <= CAPTURE;\n                    end else begin\n                        next_state <= IDLE;\n                    end\n                end\n\n                CAPTURE: begin\n                    // Capture inputs\n                    g_reg[0] <= g_0;\n                    g_reg[1] <= g_1;\n                    g_reg[2] <= g_2;\n                    g_reg[3] <= g_3;\n                    p_reg[0] <= p_0;\n                    p_reg[1] <= p_1;\n                    p_reg[2] <= p_2;\n                    p_reg[3] <= p_3;\n                    ga_reg[0] <= ga_0;\n                    ga_reg[1] <= ga_1;\n                    ga_reg[2] <= ga_2;\n                    ga_reg[3] <= ga_3;\n                    pa_reg[0] <= pa_0;\n                    pa_reg[1] <= pa_1;\n                    pa_reg[2] <= pa_2;\n                    pa_reg[3] <= pa_3;\n                    n_reg <= n;\n                    k_reg <= k;\n                    max_diversity <= 4'd0;\n                    next_state <= INIT_SUBSET;\n                end\n\n                INIT_SUBSET: begin\n                    // Determine awakenable partners\n                    awakenable_partners <= 4'd0;\n                    for (i = 0; i < 4; i = i + 1) begin\n                        if ((ga_reg[i] != 8'd0) || (pa_reg[i] != 8'd0)) begin\n                            awakenable_partners[i] <= 1'b1;\n                        end else begin\n                            awakenable_partners[i] <= 1'b0;\n                        end\n                    end\n                    subset_mask <= 4'd0;\n                    next_state <= PROCESS_SUBSET;\n                end\n\n                PROCESS_SUBSET: begin\n                    // Check subset size\n                    subset_size <= 4'd0;\n                    for (i = 0; i < 4; i = i + 1) begin\n                        if ((subset_mask[i] == 1'b1) && (awakenable_partners[i] == 1'b1)) begin\n                            subset_size <= subset_size + 4'd1;\n                        end\n                    end\n\n                    if (subset_size > k_reg) begin\n                        next_state <= NEXT_SUBSET;\n                    end else begin\n                        // Prepare current partner stats\n                        for (i = 0; i < 4; i = i + 1) begin\n                            if ((subset_mask[i] == 1'b1) && awakenable_partners[i]) begin\n                                curr_frag[i] <= ga_reg[i];\n                                curr_step[i] <= pa_reg[i];\n                            end else begin\n                                curr_frag[i] <= g_reg[i];\n                                curr_step[i] <= p_reg[i];\n                            end\n                        end\n                        subset_candidate <= subset_mask;\n                        next_state <= CALC_ANTICHAIN;\n                        antichain_max <= 4'd0;\n                    end\n                end\n\n                CALC_ANTICHAIN: begin\n                    // Process all subsets S of P\n                    if (s_mask < (1 << n_reg)) begin\n                        s_size = 4'd0;\n                        valid_antichain = 1'b1;\n\n                        // Count bits and check pairs\n                        for (i = 0; i < n_reg; i = i + 1) begin\n                            if (s_mask[i]) begin\n                                s_size = s_size + 4'd1;\n                                for (j = i+1; j < n_reg; j = j + 1) begin\n                                    if (s_mask[j]) begin\n                                        if ((curr_frag[i] > curr_frag[j] && curr_step[i] > curr_step[j]) || \n                                            (curr_frag[i] < curr_frag[j] && curr_step[i] < curr_step[j])) begin\n                                            valid_antichain = 1'b0;\n                                        end\n                                    end\n                                end\n                            end\n                        end\n\n                        if (valid_antichain && (s_size > antichain_max)) begin\n                            antichain_max <= s_size;\n                        end\n\n                        s_mask <= s_mask + 16'd1;\n                        next_state <= CALC_ANTICHAIN;\n                    end else begin\n                        next_state <= UPDATE_MAX;\n                    end\n                end\n\n                UPDATE_MAX: begin\n                    if (antichain_max > max_diversity) begin\n                        max_diversity <= antichain_max;\n                    end\n                    next_state <= NEXT_SUBSET;\n                end\n\n                NEXT_SUBSET: begin\n                    s_mask <= 16'd0;\n                    if (subset_mask == 4'b1111 || cycle_counter >= MAX_CYCLES) begin\n                        next_state <= FINISH;\n                    end else begin\n                        subset_mask <= subset_mask + 4'd1;\n                        next_state <= PROCESS_SUBSET;\n                    end\n                end\n\n                FINISH: begin\n                    result <= max_diversity;\n                    done <= 1'b1;\n                    next_state <= IDLE;\n                end\n\n                default: begin\n                    next_state <= IDLE;\n                end\n            endcase\n        end\n    end\nendmodule